package com.example.rokidkeyboardbridge;
public final class EmbodiedSceneTest{
 static int n;static void ok(boolean b,String s){n++;if(!b)throw new AssertionError(s);}
 public static void main(String[]args){String naming="私の呼び方なんだけど「旧呼称様」は呼びにくいから「マスター」にしよう";ok(UserAddressIntent.concerns(naming)&&UserAddressIntent.master(naming),"personal address bypass");ok(!UserAddressIntent.concerns("受信箱の案件名をマスターに訂正して"),"real case stays in inbox");ok(!UserAddressIntent.concerns("彼女の呼び方を教えて"),"third party excluded");ok(!UserAddressIntent.master("私の呼び方だけどマスターとは呼ばないで"),"negative preference not saved");
 EmbodiedScenePolicy p=new EmbodiedScenePolicy();p.user("ロキ、こっちに来て座って",1000);ok(p.posture()==1&&FullBodyMotionPolicy.isSeated(p.base(4)),"come and sit");p.user("そのまま話そう",1500);ok(p.posture()==1,"posture across next turn");p.answer("お隣に座りました。",FullBodyPoseCatalog.Kind.NEUTRAL,1600);ok(FullBodyMotionPolicy.isSeated(p.base(-1)),"narration matches pose");p.user("立ち上がって",2000);ok(p.posture()==0&&!FullBodyMotionPolicy.isSeated(p.base(168)),"stand explicit");for(String t:new String[]{"座らないで","座っているとは何？","彼女に座ってと言った"})ok(EmbodiedScenePolicy.postureCommand(t)==-1,"no hypothetical/negated/third-party pose");
 p.clear();p.user("よろめく仕草を見せて",3000);ok(p.clip(3100,false)==26&&p.clip(8000,false)==-1,"bounded stagger");ok(p.clip(3100,true)==-1,"navigation quiet");for(String text:new String[]{"キスして","唇をむさぼる","唇を貪る","唇を重ねて"}){p.user(text,10000);ok(p.clip(10500,false)==27,"kiss expression aliases");ok(FullBodyAffectionCue.request(text)>=4,"portrait route same kiss");}ok(KissGesturePolicy.type("唇をむさぼる")==1,"long kiss timing");p.user("やめて",11000);ok(p.clip(11500,false)==-1,"stop wins");p.user("いろんな横たわる姿を上から見せて",20000);for(int i=0;i<8;i++){long at=20000+i*4000;ok(p.selected(at)==i&&p.clip(at,false)==28+i/4,"eight overhead selections");}p.user("次の姿勢",53000);ok(p.selected(53000)>=0&&p.selected(53000)<8,"bounded next pose");p.clear();p.user("ディープキスして",54000);ok(p.kissType()==1,"new image retains long timing");p.user("もっと激しく",55000);ok(p.kissType()==4,"new image retains strong followup");p.user("普通の強さにして",56000);ok(p.kissType()==1,"new image returns to normal intensity");p.user("やめて",57000);ok(p.kissType()==-1,"stop clears intensity scene");p.clear();ok(p.clip(58000,false)==-1&&p.posture()==-1,"scene reset");System.out.println("PASS "+n+" naming/posture/stagger/kiss/overhead intent checks");}
}
